sys_script_client.script:
function onLoad() {
    if ((g_form.getValue("form_type") == 1 || g_form.getValue("form_type") == 0) && g_form.getValue("state") != 1) {
        var fields = g_form.getEditableFields();
        for (var i = 0; i < fields.length; i++) {
            g_form.setReadOnly(fields[i], true);
        }
        g_form.setReadOnly("work_notes", false);
    }
    if ((g_form.getValue("form_type") == 1 || g_form.getValue("form_type") == 0) && (g_form.getValue("state") == 2 || g_form.getValue("state") == 3) || g_form.getValue("state") == 4) {
        g_form.setReadOnly("work_notes", true);
    }
}
